const payload = $json;
const transcript = `${payload.transcript ?? ''}`.toLowerCase();
const durationSeconds = Number(payload.durationSeconds ?? 0);
const dncSignal = transcript.includes('do not call') || transcript.includes('remove me') || transcript.includes('stop calling');
const notInterested = transcript.includes('not interested') || transcript.includes('no thanks');
const emailOnly = transcript.includes('email me') || transcript.includes('just email');
const noAnswer = durationSeconds < 8 || transcript.length < 30;
let outcome;
if (dncSignal) outcome = 'DNC';
else if (noAnswer) outcome = 'no-answer';
else if (notInterested) outcome = 'not-interested';
else if (emailOnly) outcome = 'email-only';
else outcome = 'qualified';
const nextAction = {
  qualified: 'CRM stage = discovery-scheduled; calendar invite sent',
  'no-answer': 'Retry scheduler queues for next business day',
  'not-interested': 'CRM stage = closed-lost-not-interested; capture reason',
  'email-only': 'Trigger 3-touch email sequence (W03)',
  DNC: 'Block number in Vapi + flag in HubSpot do_not_contact'
};
return [{ json: { ...payload, outcome, nextAction: nextAction[outcome], downstreamWorkflow: outcome === 'email-only' ? '03-follow-up-sequence' : null } }];
